// FUNCTION: BFME2 0x000ADF41 size=79 name=?getFlipState@WorldHeightMap@@QBE_NHH@Z evidence=N:ledger tier=B hypothesis:K
// One bit per cell, eight cells to a byte, m_flipStateWidth bytes to a row.
Bool WorldHeightMap::getFlipState(Int xIndex, Int yIndex) const
{
	if (xIndex < 0 || yIndex < 0)
		return false;
	if (yIndex >= m_height)
		return false;
	if (xIndex >= m_width)
		return false;
	UnsignedInt index = yIndex * m_flipStateWidth + (xIndex >> 3);
	if (index >= m_cellFlipState.size())
		return false;
	return m_cellFlipState[index] & (1 << (xIndex & 7));
}

